<?php
require_once __DIR__.'/../includes/bootstrap.php';require_role('Company');$cid=company_id($pdo);$err='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$status=val('status',30);if(!in_array($status,['Pending','Shortlisted','Selected','Rejected'],true))$err='Invalid status.';else{$s=$pdo->prepare('UPDATE application a JOIN internship i ON i.internship_id=a.internship_id SET a.status=? WHERE a.application_id=? AND i.company_id=?');$s->execute([$status,(int)($_POST['application_id']??0),$cid]);}}
$s=$pdo->prepare('SELECT a.application_id,a.application_date,a.status,a.resume,a.cover_letter,st.name,st.department,st.year,st.CGPA,i.title FROM application a JOIN student st ON st.student_id=a.student_id JOIN internship i ON i.internship_id=a.internship_id WHERE i.company_id=? ORDER BY a.application_date DESC');$s->execute([$cid]);$rows=$s->fetchAll();$b='<h2>Applicants</h2>'.($err?'<p class="error">'.e($err).'</p>':'');
foreach($rows as $r){$b.='<section class="card"><h3>'.e($r['title']).'</h3><p>'.e($r['name']).' · '.e($r['department']).' · CGPA '.e($r['CGPA']).' · Status '.e($r['status']).'</p><p>Resume reference: '.e($r['resume']).'</p><p>'.nl2br(e($r['cover_letter'])).'</p><form method="post"><input type="hidden" name="csrf_token" value="'.e(csrf_token()).'"><input type="hidden" name="application_id" value="'.(int)$r['application_id'].'"><label>Status<select name="status">';foreach(['Pending','Shortlisted','Selected','Rejected'] as $x)$b.='<option '.($x===$r['status']?'selected':'').'>'.$x.'</option>';$b.='</select></label><button>Update status</button></form><a href="interview.php?application_id='.(int)$r['application_id'].'">Schedule interview</a></section>';}
if(!$rows)$b.='<p>No applications yet.</p>';page('Applicants',$b);
